INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20CV1CS', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h(x) = -2(x - 4)^2 + 13$ has a maximum value. What is this maximum value, and at what value of $x$ does it occur?', NULL, $lyceon_json$[{"key":"A","text":"Maximum value of $4$ at $x = 13$"},{"key":"B","text":"Maximum value of $13$ at $x = -4$"},{"key":"C","text":"Maximum value of $-13$ at $x = 4$"},{"key":"D","text":"Maximum value of $13$ at $x = 4$"}]$lyceon_json$::jsonb, 'D', NULL, E'The function $h(x) = -2(x - 4)^2 + 13$ is in vertex form $a(x - h)^2 + k$ with $a = -2$, $h = 4$, and $k = 13$. Since $a < 0$, the parabola opens downward and the vertex $(4, 13)$ is the maximum point. The maximum value is $13$ at $x = 4$. The distractor stating $x = -4$ confuses the sign of $h$ in the vertex form $(x - h)$. The distractor stating a maximum of $-13$ incorrectly negates $k$. The distractor swapping the values $4$ and $13$ reflects confusion between the vertex coordinates and their roles as the $x$-value and maximum output.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20WAUNW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A line of best fit for a data set is given by $y = 2.3x + 14.7$, where $x$ represents the number of weeks and $y$ represents the total number of units sold. According to this model, what is the best interpretation of the slope $2.3$?', NULL, $lyceon_json$[{"key":"A","text":"The predicted number of units sold increases by $2.3$ each week."},{"key":"B","text":"The predicted number of units sold after $2.3$ weeks is $14.7$."},{"key":"C","text":"The predicted total number of units sold is $2.3$."},{"key":"D","text":"The predicted number of units sold at week $0$ is $2.3$."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of a linear model represents the predicted change in $y$ for each unit increase in $x$. Here, $2.3$ means the predicted units sold increases by $2.3$ per week. Confusing $2.3$ weeks with $14.7$ units conflates the slope with the intercept. Stating the total is $2.3$ misidentifies the slope as a total. The value at week $0$ is the $y$-intercept, $14.7$, not $2.3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM216HJB8', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the solution $(x, y)$ to the system of equations? $$\\begin{cases} 3x + y = 19 \\\\ x - y = 5 \\end{cases}$$', NULL, $lyceon_json$[{"key":"A","text":"$(4, 7)$"},{"key":"B","text":"$(6, -1)$"},{"key":"C","text":"$(6, 1)$"},{"key":"D","text":"$(7, -2)$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $(6, 1)$. Adding the two equations eliminates $y$: $(3x + y) + (x - y) = 19 + 5$, which gives $4x = 24$, so $x = 6$. Substituting into $x - y = 5$ yields $6 - y = 5$, so $y = 1$. The pair $(4, 7)$ satisfies $3(4) + 7 = 19$ but fails the second equation since $4 - 7 = -3 \\neq 5$, reflecting incomplete checking. The pair $(6, -1)$ arises from a sign error when solving for $y$, using $y = 5 - x$ instead of $y = x - 5$. The pair $(7, -2)$ results from an arithmetic slip such as computing $4x = 28$ when adding the equations.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM230RVWR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A shirt originally costs $\\$62$. During a sale, the price is reduced by $15\\%$. What is the sale price of the shirt?', NULL, $lyceon_json$[{"key":"A","text":"$\\$52.70$"},{"key":"B","text":"$\\$47.00$"},{"key":"C","text":"$\\$9.30$"},{"key":"D","text":"$\\$55.80$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discount is $0.15 \\times 62 = 9.30$ dollars. The sale price is $62 - 9.30 = 52.70$ dollars. The distractor $47.00$ results from subtracting $15$ as a flat amount rather than computing $15\\%$ of the price. The distractor $9.30$ gives the discount amount itself, not the sale price after the discount is applied. The distractor $55.80$ results from applying a $10\\%$ discount instead of a $15\\%$ discount, computing $62 \\times 0.90 = 55.80$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23PF60V', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $6x + 17 = 53$?', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$36$"},{"key":"C","text":"$7$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'D', NULL, E'Subtract $17$ from both sides of $6x + 17 = 53$ to get $6x = 36$, then divide both sides by $6$ to obtain $x = 6$. The value $-6$ results from a sign error when dividing $36$ by $6$. The value $7$ comes from an arithmetic slip, such as computing $53 - 17 = 42$ and then $42 \\div 6 = 7$. The value $36$ is the intermediate result $6x = 36$ without completing the final division.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24TNSDK', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A printing company charges a fixed setup fee plus a constant rate per page. An order of $14$ pages costs $\\$173$ and an order of $37$ pages costs $\\$403$. According to this pricing model, what is the total cost, in dollars, of an order of $50$ pages?', NULL, $lyceon_json$[{"key":"A","text":"$\\$467$"},{"key":"B","text":"$\\$500$"},{"key":"C","text":"$\\$533$"},{"key":"D","text":"$\\$543$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let the cost function be $C(n) = an + b$ where $a$ is the per-page rate and $b$ is the setup fee. The rate is $a = \\frac{403 - 173}{37 - 14} = \\frac{230}{23} = 10$ dollars per page. Using $C(14) = 173$: $10(14) + b = 173$, so $b = 33$. Therefore $C(50) = 10(50) + 33 = 533$ dollars. The value $\\$467$ results from a sign error, computing $500 - 33$ instead of $500 + 33$. The value $\\$500$ reflects partial reasoning that finds only the variable cost $10 \\times 50$ without adding the setup fee. The value $\\$543$ comes from an arithmetic slip such as computing $10 \\times 14 = 130$ instead of $140$, yielding $b = 43$ and $C(50) = 543$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25FTJES', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(2, 11)$ and $(5, 23)$. Which of the following equations represents this line?', NULL, $lyceon_json$[{"key":"A","text":"$y = 4x - 3$"},{"key":"B","text":"$y = 4x + 3$"},{"key":"C","text":"$y = 4x + 11$"},{"key":"D","text":"$y = 12x + 3$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope is $\\frac{23 - 11}{5 - 2} = \\frac{12}{3} = 4$. Using the point $(2, 11)$ in point-slope form: $y - 11 = 4(x - 2)$, which gives $y = 4x - 8 + 11 = 4x + 3$. The equation $y = 4x - 3$ has the correct slope but a sign error in the $y$-intercept calculation. The equation $y = 4x + 11$ uses the $y$-coordinate of the first point as the intercept without computing $b$ properly, representing partial reasoning. The equation $y = 12x + 3$ uses the numerator of the slope fraction ($12$) as the slope instead of dividing by the run.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25HTFII', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'Data collected from a study reveal a strong positive linear association between the number of hours studied and exam scores. Which of the following best describes this association?', NULL, $lyceon_json$[{"key":"A","text":"As hours studied increases, exam scores tend to decrease."},{"key":"B","text":"As hours studied increases, exam scores remain constant."},{"key":"C","text":"There is no relationship between hours studied and exam scores."},{"key":"D","text":"As hours studied increases, exam scores tend to increase."}]$lyceon_json$::jsonb, 'D', NULL, E'A strong positive linear association means that as one variable increases, the other also tends to increase. Exam scores tending to decrease would describe a negative association. No relationship would mean no discernible pattern. Scores remaining constant would describe no association with the variable.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25WLVGK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A cone has a volume of $147\\pi$ cubic units and a height of $9$ units. What is the radius, in units, of the base of the cone?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h$. Substituting the given values: $147\\pi = \\frac{1}{3}\\pi r^2(9)$. Dividing both sides by $\\pi$: $147 = \\frac{9r^2}{3} = 3r^2$. Solving: $r^2 = \\frac{147}{3} = 49$, so $r = 7$. A common error is forgetting the $\\frac{1}{3}$ factor, leading to $r^2 = \\frac{147}{9} = 16.\\overline{3}$, which gives a non-integer radius. Another error is solving for $r^2$ correctly but reporting $49$ instead of taking the square root.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM263V7VD', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'What is the greatest integer value of $x$ that satisfies the inequality $-3(2x + 7) + 4x \\geq 5x - 9$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-2', ARRAY['-2'], E'Distribute $-3$ across $(2x + 7)$ to get $-6x - 21 + 4x \\geq 5x - 9$. Combine like terms on the left side: $-2x - 21 \\geq 5x - 9$. Add $2x$ to both sides: $-21 \\geq 7x - 9$. Add $9$ to both sides: $-12 \\geq 7x$, which gives $x \\leq -\\frac{12}{7}$. Since $-\\frac{12}{7} \\approx -1.714$, the greatest integer satisfying this inequality is $-2$. A common error is to get $x \\leq \\frac{12}{7}$ by dropping the negative sign, which would incorrectly give a greatest integer of $1$. Another error is to distribute $-3$ only to $2x$ and not to $7$, leading to a different boundary value.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM275C5US', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains 8 yellow buttons, 11 white buttons, and 6 black buttons. If one button is selected at random, what is the probability that it is yellow?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{6}{25}$"},{"key":"B","text":"$\\frac{11}{25}$"},{"key":"C","text":"$\\frac{8}{17}$"},{"key":"D","text":"$\\frac{8}{25}$"}]$lyceon_json$::jsonb, 'D', NULL, E'The total number of buttons is $8 + 11 + 6 = 25$. The probability of selecting a yellow button is $\\frac{8}{25}$. The distractor $\\frac{11}{25}$ uses the count of white buttons instead of yellow. The distractor $\\frac{8}{17}$ incorrectly uses $11 + 6 = 17$ as the total, omitting the yellow buttons from the denominator. The distractor $\\frac{6}{25}$ uses the count of black buttons instead of yellow.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27QY8QZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health magazine reports that people who drink at least 3 cups of green tea per day have lower rates of heart disease than those who do not drink green tea. The report is based on a survey in which participants self-reported their tea consumption and medical history. Which of the following is the most appropriate conclusion from this study?', NULL, $lyceon_json$[{"key":"A","text":"Drinking green tea causes a reduction in heart disease."},{"key":"B","text":"Green tea has no effect on heart disease because the study was not a controlled experiment."},{"key":"C","text":"People who do not drink green tea should begin drinking it to prevent heart disease."},{"key":"D","text":"There is an association between drinking green tea and lower rates of heart disease."}]$lyceon_json$::jsonb, 'D', NULL, E'This is an observational study, not a controlled experiment, so it can establish an association but cannot establish causation. The distractor claiming causation goes beyond what an observational study supports. The distractor recommending green tea to prevent heart disease assumes a causal relationship that has not been established. The distractor claiming no effect is too strong; an observational study can identify associations even though it cannot prove causation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27SBITV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'In a school, $35\\%$ of students study French and $42\\%$ study Spanish. If $17\\%$ study both languages, what percent of students study neither French nor Spanish?', NULL, $lyceon_json$[{"key":"A","text":"$60\\%$"},{"key":"B","text":"$23\\%$"},{"key":"C","text":"$6\\%$"},{"key":"D","text":"$40\\%$"}]$lyceon_json$::jsonb, 'D', NULL, E'By the inclusion-exclusion principle, the percentage who study at least one language is $35 + 42 - 17 = 60\\%$. Therefore, the percentage who study neither is $100 - 60 = 40\\%$. The distractor $23\\%$ comes from computing $100 - 35 - 42 = 23$ without adding back the overlap. The distractor $6\\%$ results from computing $42 - 35 - 17 + 16$ erroneously. The distractor $60\\%$ gives the percentage who study at least one language rather than neither.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28BSDPP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many real solutions does the equation $3x^2 - 10x + 9 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"Zero"},{"key":"B","text":"Exactly one"},{"key":"C","text":"Exactly two"},{"key":"D","text":"Infinitely many"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is $b^2 - 4ac = (-10)^2 - 4(3)(9) = 100 - 108 = -8$. Since the discriminant is negative, the equation has zero real solutions. Selecting exactly one solution reflects confusion with a zero discriminant. Selecting exactly two reflects the assumption that all quadratics have two real roots. Selecting infinitely many reflects a fundamental misunderstanding of polynomial equations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28YG3PW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A recipe calls for $\\frac{7}{3}$ cups of rice to serve $11$ people. If the recipe is scaled to serve $33$ people, how many cups of rice are needed?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$\\frac{77}{3}$"},{"key":"C","text":"$\\frac{21}{11}$"},{"key":"D","text":"$\\frac{7}{9}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $33$ people is $3$ times $11$ people, the amount of rice must also be tripled: $\\frac{7}{3} \\times 3 = 7$ cups. The distractor $\\frac{77}{3}$ results from multiplying $\\frac{7}{3} \\times 11$ instead of the scale factor $3$. The distractor $\\frac{21}{11}$ comes from dividing the numerator''s triple by the original number of people. The distractor $\\frac{7}{9}$ comes from dividing $\\frac{7}{3}$ by $3$ instead of multiplying.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2913IRV', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $3x - 7y = 21$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$3$"},{"key":"C","text":"$7$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'A', NULL, E'The $y$-intercept occurs when $x = 0$. Substituting into $3(0) - 7y = 21$ gives $-7y = 21$, so $y = -3$. The value $3$ results from a sign error when dividing $21$ by $-7$. The value $7$ reflects a concept gap, confusing the coefficient of $y$ with the intercept. The value $21$ comes from reading the constant term on the right side of the equation without solving for $y$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29B6T7F', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A print shop charges $\\$23$ per poster and a one-time design fee of $\\$47$. A customer has at most $\\$300$ to spend. Which inequality can be used to determine $n$, the number of posters the customer can order?', NULL, $lyceon_json$[{"key":"A","text":"$23n + 47 \\geq 300$"},{"key":"B","text":"$23n - 47 \\leq 300$"},{"key":"C","text":"$47n + 23 \\leq 300$"},{"key":"D","text":"$23n + 47 \\leq 300$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $23n + 47 \\leq 300$. The total cost is the per-poster charge of $\\$23$ multiplied by $n$ plus the one-time design fee of $\\$47$, and this total must be at most $\\$300$, giving $23n + 47 \\leq 300$. The choice $23n - 47 \\leq 300$ incorrectly subtracts the design fee instead of adding it to the total cost. The choice $47n + 23 \\leq 300$ swaps the per-poster rate and the fixed fee, applying the fixed fee as if it were charged per poster. The choice $23n + 47 \\geq 300$ sets up the cost as needing to be at least $\\$300$, which reverses the budget constraint.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A9B84J', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which inequality represents all values of $x$ that satisfy $9x + 17 > 71$?', NULL, $lyceon_json$[{"key":"A","text":"$x < 6$"},{"key":"B","text":"$x > \\frac{88}{9}$"},{"key":"C","text":"$x > \\frac{71}{9}$"},{"key":"D","text":"$x > 6$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $x > 6$. Subtract $17$ from both sides of $9x + 17 > 71$ to get $9x > 54$, then divide both sides by $9$ to obtain $x > 6$. The choice $x < 6$ results from reversing the inequality direction even though division by a positive number does not change the direction. The choice $x > \\frac{71}{9}$ comes from dividing $71$ by $9$ without first subtracting $17$, skipping a necessary step. The choice $x > \\frac{88}{9}$ results from adding $17$ to $71$ instead of subtracting, yielding $9x > 88$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AAR58R', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'The equation $\\frac{x^2 - 13x + 36}{x - 4} = x + k$ is true for all values of $x \\neq 4$, where $k$ is a constant. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-9', ARRAY['-9'], E'The numerator $x^2 - 13x + 36$ factors as $(x - 4)(x - 9)$, since $(-4) + (-9) = -13$ and $(-4)(-9) = 36$. Dividing by $(x - 4)$ yields $\\frac{(x - 4)(x - 9)}{x - 4} = x - 9$ for $x \\neq 4$. Comparing with $x + k$ gives $k = -9$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ADN5B2', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{5x^3 - 20x^2 + 15x}{5x}$ is rewritten in the form $x^2 + bx + c$, where $b$ and $c$ are constants, what is the value of $b + c$?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$7$"},{"key":"D","text":"$-4$"}]$lyceon_json$::jsonb, 'A', NULL, E'Dividing each term of the numerator by $5x$: $\\frac{5x^3}{5x} = x^2$, $\\frac{-20x^2}{5x} = -4x$, $\\frac{15x}{5x} = 3$. So the expression simplifies to $x^2 - 4x + 3$, giving $b = -4$ and $c = 3$. Therefore $b + c = -4 + 3 = -1$. The distractor $-7$ comes from computing $b + c = -4 + (-3)$, a sign error on the constant term. The distractor $7$ comes from using $b = 4$ and $c = 3$, ignoring the negative sign on $b$. The distractor $-4$ comes from giving only the value of $b$ without adding $c$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B8C4QH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle in the $xy$-plane has the equation $(x - 4)^2 + (y + 7)^2 = 169$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'The standard form of a circle is $(x - h)^2 + (y - k)^2 = r^2$. Comparing with $(x - 4)^2 + (y + 7)^2 = 169$, we see $r^2 = 169$, so $r = \\sqrt{169} = 13$. A common error is reporting $169$ as the radius instead of taking the square root. Another error is misidentifying the center coordinates and attempting to use them in the radius calculation.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BE26O2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A $26$-foot ladder leans against a vertical wall. The base of the ladder is on level ground, and the ladder makes an angle $\\theta$ with the ground such that $\\cos(\\theta) = \\frac{5}{13}$. How many feet up the wall does the ladder reach?', NULL, $lyceon_json$[{"key":"A","text":"$10$"},{"key":"B","text":"$14$"},{"key":"C","text":"$24$"},{"key":"D","text":"$30$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $\\cos(\\theta) = \\frac{5}{13}$ and the ladder (hypotenuse) is $26$ feet, the horizontal distance from the wall is $26 \\times \\frac{5}{13} = 10$ feet. By the Pythagorean theorem, the height up the wall is $\\sqrt{26^2 - 10^2} = \\sqrt{676 - 100} = \\sqrt{576} = 24$ feet. The value $10$ is the horizontal distance, not the vertical height, resulting from stopping after the first step. The value $14$ comes from an arithmetic error when computing $\\sqrt{576}$. The value $30$ results from incorrectly adding $26$ and a miscomputed component.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C3II8S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'grid_in', E'A survey of 144 adults recorded whether each person exercises regularly and whether each person reports high stress. Of the 144 adults, 54 exercise regularly and 90 do not exercise regularly. Among those who exercise regularly, $\\frac{2}{9}$ report high stress. Among those who do not exercise regularly, $\\frac{1}{3}$ report high stress. If one adult is selected at random from all those who report high stress, what is the probability that this person exercises regularly? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2/7', ARRAY['2/7', '0.285', '.285', '0.286', '.286'], E'Among the 54 adults who exercise regularly, $\\frac{2}{9} \\times 54 = 12$ report high stress. Among the 90 adults who do not exercise regularly, $\\frac{1}{3} \\times 90 = 30$ report high stress. The total number of adults who report high stress is $12 + 30 = 42$. The probability that a randomly selected high-stress adult exercises regularly is $\\frac{12}{42} = \\frac{2}{7}$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ETAA8P', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A machine fills $37$ bottles every $4$ minutes. At this rate, how many bottles does the machine fill in $20$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$148$"},{"key":"B","text":"$185$"},{"key":"C","text":"$74$"},{"key":"D","text":"$740$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{37}{4}$ bottles per minute. In $20$ minutes, the machine fills $\\frac{37}{4} \\times 20 = 37 \\times 5 = 185$ bottles. The distractor $148$ results from multiplying $37 \\times 4$ instead of dividing. The distractor $74$ comes from doubling $37$ without accounting for the full time. The distractor $740$ results from multiplying $37 \\times 20$ without dividing by $4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EV2D9B', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $47^\\circ$ and the exterior angle at vertex $R$ measures $131^\\circ$. What is the measure, in degrees, of angle $Q$?', NULL, $lyceon_json$[{"key":"A","text":"$49$"},{"key":"B","text":"$84$"},{"key":"C","text":"$96$"},{"key":"D","text":"$133$"}]$lyceon_json$::jsonb, 'B', NULL, E'The exterior angle at vertex $R$ is supplementary to the interior angle at $R$, so the interior angle $R = 180 - 131 = 49^\\circ$. By the triangle angle sum property, $P + Q + R = 180^\\circ$, so $47 + Q + 49 = 180$, giving $Q = 84^\\circ$. The value $49$ comes from finding the interior angle at $R$ but stopping there without solving for $Q$. The value $96$ results from subtracting only $47$ from $180$ and dividing by $2$ or misapplying the exterior angle theorem. The value $133$ comes from subtracting $47$ from $180$ without accounting for angle $R$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EY3HGM', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $3x^2 + 9x - 15$?', NULL, $lyceon_json$[{"key":"A","text":"$3(x^2 - 3x - 5)$"},{"key":"B","text":"$3(x^2 + 3x + 5)$"},{"key":"C","text":"$3(x^2 + 9x - 15)$"},{"key":"D","text":"$3(x^2 + 3x - 5)$"}]$lyceon_json$::jsonb, 'D', NULL, E'Factoring 3 from each term of $3x^2 + 9x - 15$ gives $3(x^2 + 3x - 5)$, since $3 \\cdot x^2 = 3x^2$, $3 \\cdot 3x = 9x$, and $3 \\cdot (-5) = -15$. The distractor $3(x^2 + 3x + 5)$ incorrectly changes the sign of the constant from $-5$ to $+5$. The distractor $3(x^2 + 9x - 15)$ fails to divide the coefficients by 3 after factoring. The distractor $3(x^2 - 3x - 5)$ incorrectly negates the linear term.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FC4VH5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle $JKL$, the right angle is at vertex $K$. If $JK = 15$ and $JL = 17$, what is the value of $\\sin(L)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15/17', ARRAY['15/17', '0.882', '.882'], E'In right triangle $JKL$ with the right angle at $K$, the hypotenuse is $JL = 17$. The side opposite angle $L$ is $JK = 15$. Therefore, $\\sin(L) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{15}{17}$. A common error is confusing which side is opposite angle $L$ and which is adjacent, which would yield $\\cos(L)$ instead. Another error is using $KL$ (which equals $\\sqrt{17^2 - 15^2} = 8$) as the opposite side.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G53HFZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set consists of the values $14, 19, 19, 23, 27, 31$. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$19$"},{"key":"B","text":"$21$"},{"key":"C","text":"$22.17$"},{"key":"D","text":"$23$"}]$lyceon_json$::jsonb, 'B', NULL, E'With $6$ values in order, the median is the average of the $3$rd and $4$th values: $\\frac{19 + 23}{2} = 21$. The distractor $19$ is the mode, not the median. The distractor $22.17$ is the mean ($\\frac{133}{6} \\approx 22.17$), confused with the median. The distractor $23$ is the $4$th value alone rather than the average of the two middle values.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GH907T', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $7$ and a height of $11$. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$77\\pi$"},{"key":"B","text":"$154\\pi$"},{"key":"C","text":"$539\\pi$"},{"key":"D","text":"$1078\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi(7^2)(11) = \\pi(49)(11) = 539\\pi$. The value $77\\pi$ comes from using $\\pi r h$ instead of $\\pi r^2 h$, treating the radius as not squared. The value $154\\pi$ results from using $2\\pi r h$, which is the lateral surface area formula rather than the volume formula. The value $1078\\pi$ comes from doubling the correct volume, perhaps confusing it with a different solid.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KI8A8D', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to the equation $x^2 + 3x - 54 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 3$ and $x = -18$"},{"key":"B","text":"$x = 9$ and $x = -6$"},{"key":"C","text":"$x = -9$ and $x = -6$"},{"key":"D","text":"$x = -9$ and $x = 6$"}]$lyceon_json$::jsonb, 'D', NULL, E'Factoring $x^2 + 3x - 54 = (x + 9)(x - 6) = 0$ gives $x = -9$ and $x = 6$, since $9 + (-6) = 3$ and $9 \\times (-6) = -54$. The distractor $x = 9$ and $x = -6$ reverses the signs of both roots. The distractor $x = -9$ and $x = -6$ incorrectly makes both roots negative, which would yield a positive sum rather than $3$. The distractor $x = 3$ and $x = -18$ uses a factor pair of $-54$ whose sum is $-15$, not $3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L8RYCC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'Triangles $ABC$ and $DEF$ are similar. The side lengths of triangle $ABC$ are $7$, $11$, and $13$. If the shortest side of triangle $DEF$ has length $21$, what is the length of the longest side of triangle $DEF$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '39', ARRAY['39'], E'Since the triangles are similar, corresponding sides are proportional. The shortest side of triangle $ABC$ is $7$, and the shortest side of triangle $DEF$ is $21$, so the scale factor is $\\frac{21}{7} = 3$. The longest side of triangle $ABC$ is $13$, so the longest side of triangle $DEF$ is $13 \\times 3 = 39$. A common error is using the wrong pair of corresponding sides, such as dividing $21$ by $11$ or $13$ instead of $7$, which produces an incorrect scale factor.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LD5L7D', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A car travels $d$ miles using $g$ gallons of fuel. When $d = 247$ and $g = 13$, how many gallons of fuel are needed to travel $361$ miles at the same rate?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '19', ARRAY['19'], E'The rate is $\\frac{247}{13} = 19$ miles per gallon. To travel $361$ miles requires $\\frac{361}{19} = 19$ gallons exactly. The fuel needed equals $\\frac{361 \\times 13}{247} = \\frac{4693}{247} = 19$ gallons. A common error is computing the rate incorrectly or setting up the proportion with inverted terms.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LEHCMT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of 400 households in a county and finds that the mean monthly electricity bill is $\\$137$ with a margin of error of $\\$9$ at a $95\\%$ confidence level. Which of the following changes to the study design would most likely decrease the margin of error?', NULL, $lyceon_json$[{"key":"A","text":"Surveying 100 households instead of 400"},{"key":"B","text":"Surveying 900 households instead of 400"},{"key":"C","text":"Using a $99\\%$ confidence level instead of $95\\%$"},{"key":"D","text":"Surveying only households with electricity bills above $\\$100$"}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error is inversely related to the square root of the sample size. Increasing the sample from 400 to 900 households would decrease the margin of error. Decreasing the sample to 100 would increase the margin of error, not decrease it. Raising the confidence level to $99\\%$ would widen the interval, increasing the margin of error. Restricting the sample to households with bills above $\\$100$ introduces selection bias and does not address the margin of error in a valid way.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M6WQ7N', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the system of equations have infinitely many solutions? $$\\begin{cases} 6x - 9y = 15 \\\\ -4x + ky = -10 \\end{cases}$$', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$\\frac{2}{3}$"},{"key":"C","text":"$6$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $6$. For infinitely many solutions, the second equation must be a constant multiple of the first. The ratio of the $x$-coefficients is $\\frac{-4}{6} = -\\frac{2}{3}$, and the ratio of the constants is $\\frac{-10}{15} = -\\frac{2}{3}$, confirming the multiplier is $-\\frac{2}{3}$. Setting $\\frac{k}{-9} = -\\frac{2}{3}$ gives $k = -9 \\cdot \\left(-\\frac{2}{3}\\right) = 6$. The value $-6$ results from a sign error when multiplying $-9$ by $-\\frac{2}{3}$, incorrectly retaining the negative. The value $\\frac{2}{3}$ comes from computing the ratio $\\frac{-4}{6}$ but stopping there without applying it to the $y$-coefficient. The value $15$ arises from incorrectly cross-multiplying coefficients from different columns of the system.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N053J8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are drawn from voters in a district. Sample 1 of 600 voters estimates that $52\\%$ support a ballot measure, with a margin of error of $\\pm 4$ percentage points. Sample 2 of 1,500 voters estimates that $46\\%$ support the measure, with a margin of error of $\\pm 2.5$ percentage points. Based on these results, which of the following conclusions is most supported?', NULL, $lyceon_json$[{"key":"A","text":"The ballot measure will certainly fail because Sample 2, with its smaller margin of error, shows less than $50\\%$ support."},{"key":"B","text":"The two confidence intervals overlap, so the data are consistent with the true level of support being between $48\\%$ and $48.5\\%$."},{"key":"C","text":"The two confidence intervals overlap, so based on these data alone, one cannot conclude with certainty whether the true level of support is above or below $50\\%$."},{"key":"D","text":"Sample 1 is more reliable because it shows majority support for the measure."}]$lyceon_json$::jsonb, 'C', NULL, E'Sample 1 gives a confidence interval of $48\\%$ to $56\\%$, and Sample 2 gives $43.5\\%$ to $48.5\\%$. These intervals overlap in the range $48\\%$ to $48.5\\%$, meaning the data do not definitively establish whether the true support is above or below $50\\%$. The distractor claiming the measure will certainly fail overstates what a confidence interval can conclude. The distractor narrowing the true value to exactly $48\\%$ to $48.5\\%$ misinterprets overlap as pinpointing the parameter. The distractor claiming Sample 1 is more reliable confuses the direction of the estimate with the quality of the sample; larger samples generally yield more precise estimates.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N6VJE3', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'A farmer purchases two types of feed. Type A costs $\\$7$ per bag and Type B costs $\\$11$ per bag. The farmer buys $23$ bags in total for $\\$209$. How many bags of Type B does the farmer buy?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12', ARRAY['12'], E'Let $a$ be the number of Type A bags and $b$ be the number of Type B bags. The system is $a + b = 23$ and $7a + 11b = 209$. From the first equation, $a = 23 - b$. Substituting into the second equation: $7(23 - b) + 11b = 209$, which gives $161 - 7b + 11b = 209$, so $4b = 48$ and $b = 12$. A common error is solving for $a$ instead of $b$, which gives $11$ bags. Another error is setting up the cost equation incorrectly by swapping the prices, which would yield a different count.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OVPOOE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $26$. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$13\\pi$"},{"key":"B","text":"$26\\pi$"},{"key":"C","text":"$169\\pi$"},{"key":"D","text":"$676\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The radius is half the diameter: $r = \\frac{26}{2} = 13$. The area is $A = \\pi r^2 = \\pi(13)^2 = 169\\pi$. The value $13\\pi$ results from using $\\pi r$ instead of $\\pi r^2$, omitting the squaring step. The value $26\\pi$ comes from computing $\\pi d$, which is the circumference formula, not the area formula. The value $676\\pi$ results from using the diameter ($26$) instead of the radius in $\\pi r^2$, computing $\\pi(26)^2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PI0UOJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A class of 34 students was surveyed about whether they play a sport and whether they play a musical instrument. Of the 34 students, 19 play a sport, 13 play a musical instrument, and 6 play both. If a student is selected at random from those who play a sport, what is the probability that the student also plays a musical instrument?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{6}{13}$"},{"key":"B","text":"$\\frac{6}{34}$"},{"key":"C","text":"$\\frac{6}{19}$"},{"key":"D","text":"$\\frac{13}{19}$"}]$lyceon_json$::jsonb, 'C', NULL, E'This is a conditional probability question. Given that the student plays a sport, the sample space is the 19 students who play a sport. Of those 19, exactly 6 also play a musical instrument. Therefore the conditional probability is $\\frac{6}{19}$. The distractor $\\frac{6}{13}$ divides the overlap by the number who play an instrument, reversing the condition. The distractor $\\frac{6}{34}$ divides by the total class size instead of restricting to sport players. The distractor $\\frac{13}{19}$ uses the total number of instrument players rather than the overlap with sport players.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q485TF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = x^2 - 6x + 11$. What is the value of $g(2)$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$-1$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 2$: $g(2) = (2)^2 - 6(2) + 11 = 4 - 12 + 11 = 3$. The distractor $5$ results from an arithmetic slip such as computing $6 \\times 2 = 10$ instead of $12$, giving $4 - 10 + 11 = 5$. The distractor $7$ comes from ignoring the subtraction of $6x$ and computing only $4 + 11 = 15$, then subtracting $8$ by partial reasoning. The distractor $-1$ comes from a sign error such as computing $-4 - 12 + 11 = -5$ or similar miscalculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QAS7H5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collects data on temperature ($x$, in degrees Celsius) and the rate of a chemical reaction ($y$, in mol/s). The exponential model $y = 0.47 \\cdot 1.083^x$ fits the data. Based on this model, which of the following is closest to the percent increase in the reaction rate for each $1^\\circ\\text{C}$ increase in temperature?', NULL, $lyceon_json$[{"key":"A","text":"$0.83\\%$"},{"key":"B","text":"$8.3\\%$"},{"key":"C","text":"$47\\%$"},{"key":"D","text":"$1.083\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'In the exponential model $y = 0.47 \\cdot 1.083^x$, the base $1.083$ indicates that for each unit increase in $x$, $y$ is multiplied by $1.083$. This corresponds to an $8.3\\%$ increase per degree Celsius ($1.083 - 1 = 0.083 = 8.3\\%$). The distractor $0.83\\%$ results from misplacing the decimal point. The distractor $47\\%$ confuses the initial coefficient $0.47$ with a growth rate. The distractor $1.083\\%$ uses the base directly as a percentage without subtracting $1$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QTXXG6', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What value of $x$ satisfies $\\frac{2x + 9}{3} = \\frac{x - 1}{2} + 5$?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$3$"},{"key":"C","text":"$9$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiply every term by $6$ to clear the denominators: $2(2x + 9) = 3(x - 1) + 30$. Expanding gives $4x + 18 = 3x - 3 + 30$, which simplifies to $4x + 18 = 3x + 27$. Subtracting $3x$ and then $18$ from both sides yields $x = 9$. The value $-9$ arises from a sign error when isolating $x$. The value $3$ results from an equation-setup error such as failing to multiply the standalone $5$ by the common denominator. The value $15$ comes from an arithmetic slip like computing $-3 + 30 = 33$ instead of $27$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QY0DMS', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'grid_in', E'Consider the system of equations: $$\\begin{cases} 5x - 3y = 2x + 18 \\\\ 7y - 4x = 3(y - x) + 21 \\end{cases}$$ What is the value of $x - 2y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-3', ARRAY['-3'], E'First simplify each equation. The first equation $5x - 3y = 2x + 18$ becomes $3x - 3y = 18$, or $x - y = 6$. The second equation $7y - 4x = 3(y - x) + 21$ expands to $7y - 4x = 3y - 3x + 21$, which simplifies to $4y - x = 21$. From $x - y = 6$, we get $x = y + 6$. Substituting into $4y - x = 21$: $4y - (y + 6) = 21$, so $3y = 27$ and $y = 9$. Then $x = 9 + 6 = 15$. Therefore $x - 2y = 15 - 2(9) = 15 - 18 = -3$. A common error is to solve for $x$ or $y$ alone and submit that value instead of computing $x - 2y$. Another error is to incorrectly simplify the second equation, for example by distributing $3$ only to $y$ and not to $-x$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S8WRUF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A triangle has a base of $18$ units and a height of $13$ units. What is the area, in square units, of the triangle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '117', ARRAY['117'], E'The area of a triangle is $A = \\frac{1}{2} \\times \\text{base} \\times \\text{height} = \\frac{1}{2}(18)(13) = \\frac{234}{2} = 117$ square units. A common error is forgetting the $\\frac{1}{2}$ factor and computing $18 \\times 13 = 234$ instead. Another error is misremembering the formula as $\\frac{1}{3}bh$, which gives $78$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SXL7IH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A store increases the price of an item by $20\\%$ and then offers a $20\\%$ discount on the new price. If the original price was $\\$85$, what is the final price, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '81.6', ARRAY['408/5', '81.6'], E'After a $20\\%$ increase, the price becomes $85 \\times 1.20 = 102$ dollars. After a $20\\%$ discount on $102$, the final price is $102 \\times 0.80 = 81.60$ dollars. A common error is assuming the two percentage changes cancel out and the final price equals the original. Another error involves applying both percentages to the original price separately.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T7PT14', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 13x - 47$. What is the value of $g(6)$?', NULL, $lyceon_json$[{"key":"A","text":"$-31$"},{"key":"B","text":"$25$"},{"key":"C","text":"$31$"},{"key":"D","text":"$78$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 6$ into $g(x) = 13x - 47$ gives $g(6) = 13(6) - 47 = 78 - 47 = 31$. The value $-31$ results from a sign error, computing $47 - 78$ instead of $78 - 47$. The value $25$ comes from an arithmetic slip such as computing $13 \\times 6 = 72$ instead of $78$, giving $72 - 47 = 25$. The value $78$ results from computing only $13 \\times 6$ without subtracting $47$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TCX4XR', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $(2x - 7)(3x + 4)$?', NULL, $lyceon_json$[{"key":"A","text":"$6x^2 + 13x - 28$"},{"key":"B","text":"$6x^2 - 29x - 28$"},{"key":"C","text":"$6x^2 - 13x - 28$"},{"key":"D","text":"$6x^2 - 13x + 28$"}]$lyceon_json$::jsonb, 'C', NULL, E'Expanding $(2x - 7)(3x + 4)$ using FOIL: $(2x)(3x) = 6x^2$, $(2x)(4) = 8x$, $(-7)(3x) = -21x$, $(-7)(4) = -28$. Combining: $6x^2 + 8x - 21x - 28 = 6x^2 - 13x - 28$. The distractor $6x^2 - 29x - 28$ results from incorrectly adding the magnitudes $8 + 21 = 29$ with a negative sign instead of computing $8 - 21 = -13$. The distractor $6x^2 + 13x - 28$ flips the sign of the linear term. The distractor $6x^2 - 13x + 28$ incorrectly makes the constant positive.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TE7QZM', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A linear function $f$ satisfies $f(2) = 11$ and $f(6) = 31$. What is the value of $f(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$1$"},{"key":"C","text":"$5$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate of change is $\\frac{31 - 11}{6 - 2} = \\frac{20}{4} = 5$. Using $f(2) = 11$: $11 = 5(2) + b$, so $b = 1$, meaning $f(0) = 1$. The value $-1$ arises from a sign error when solving for $b$, such as computing $10 - 11 = -1$. The value $5$ reflects partial reasoning where the student identifies the slope but reports it as the answer instead of finding the $y$-intercept. The value $21$ comes from an equation-setup error, such as averaging $11$ and $31$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UGZIX5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 250 voters in a city found that $43\\%$ plan to vote for Candidate X in an upcoming election. The margin of error for this estimate is $\\pm 4$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $43\\%$ of all voters in the city plan to vote for Candidate X."},{"key":"B","text":"It is plausible that between $39\\%$ and $47\\%$ of all voters in the city plan to vote for Candidate X."},{"key":"C","text":"Between $39\\%$ and $47\\%$ of the 250 voters sampled plan to vote for Candidate X."},{"key":"D","text":"If the survey were repeated, exactly $43\\%$ of respondents would plan to vote for Candidate X every time."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of $\\pm 4$ percentage points means the confidence interval for the true population proportion is from $43 - 4 = 39\\%$ to $43 + 4 = 47\\%$. The plausible range applies to all voters in the city, not just the sample. The distractor stating exactly $43\\%$ ignores sampling variability. The distractor applying the interval to the sample confuses the sample statistic with the population parameter. The distractor claiming the result would be identical every time misunderstands sampling variability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VCW0RZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. One of the alternate interior angles measures $53^\\circ$. What is the measure, in degrees, of the supplement of the other alternate interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$53$"},{"key":"B","text":"$107$"},{"key":"C","text":"$127$"},{"key":"D","text":"$143$"}]$lyceon_json$::jsonb, 'C', NULL, E'Alternate interior angles formed by parallel lines and a transversal are congruent, so the other alternate interior angle also measures $53^\\circ$. The supplement of a $53^\\circ$ angle is $180 - 53 = 127$ degrees. The value $53$ results from finding the alternate interior angle but not taking the supplement. The value $107$ comes from incorrectly doubling $53$ and subtracting from $160$. The value $143$ results from subtracting $53$ from $196$ or a similar arithmetic error in finding the supplement.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VI4HK2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university researcher recruited 200 volunteers from a campus fitness center and randomly assigned half to a high-protein diet and half to a standard diet. After 12 weeks, the high-protein group had a significantly greater increase in muscle mass. A news article reported: "Study proves high-protein diets build more muscle for all adults." Which of the following best explains why the news article''s claim is NOT fully supported by the study?', NULL, $lyceon_json$[{"key":"A","text":"The study used random assignment, so it can establish causation, but the volunteers came from a fitness center and may not represent all adults."},{"key":"B","text":"The study did not use random assignment, so causation cannot be established."},{"key":"C","text":"A sample of 200 is too small to draw any conclusion."},{"key":"D","text":"The 12-week duration is insufficient to measure changes in muscle mass."}]$lyceon_json$::jsonb, 'A', NULL, E'The study did use random assignment (half to each diet), so a causal link between the high-protein diet and muscle mass increase is supported for the study participants. However, the volunteers were recruited from a campus fitness center, meaning they are not a random sample of all adults. This limits generalizability. The distractor claiming no random assignment contradicts the study design described. The distractor claiming 200 is too small is not supported; 200 with random assignment is adequate for valid inference about the study population. The distractor about 12 weeks being insufficient is not a statistical design flaw relevant to the claim about generalizability.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VJOQPK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers wanted to test whether a new fertilizer increases tomato yield. They randomly assigned 40 tomato plants to receive the new fertilizer and 40 tomato plants to receive a standard fertilizer. After 8 weeks, the mean yield of the new-fertilizer group was significantly higher than that of the standard-fertilizer group. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new fertilizer causes increased tomato yield compared to the standard fertilizer, but the result applies only to the 80 plants in the study."},{"key":"B","text":"There is an association between the type of fertilizer and tomato yield, but causation cannot be established."},{"key":"C","text":"The new fertilizer causes increased tomato yield for all tomato plants everywhere."},{"key":"D","text":"The result is not meaningful because 80 plants is too small a sample."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the study used random assignment to treatment groups, a causal conclusion is justified. However, the plants were not randomly selected from a larger population, so the causal finding applies only to the 80 plants studied, not to all tomato plants. The distractor claiming only association ignores that random assignment allows causal inference. The distractor generalizing to all tomato plants everywhere overstates the scope, since the plants were not randomly sampled from a broader population. The distractor dismissing the study for having too small a sample is not supported; a sample of 80 with random assignment can produce valid statistical conclusions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VYG6HO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set has $5$ values listed in increasing order: $a, 38, 41, 53, 67$. If the mean of the data set is $46$, what is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$31$"},{"key":"B","text":"$33$"},{"key":"C","text":"$38$"},{"key":"D","text":"$27$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of all five values must equal $5 \\times 46 = 230$. So $a + 38 + 41 + 53 + 67 = 230$, giving $a + 199 = 230$ and $a = 31$. The distractor $33$ results from a subtraction error ($230 - 197$). The distractor $38$ assumes $a$ equals the next value in the set. The distractor $27$ comes from an error such as computing $230 - 203$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WIQVBE', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'A line is perpendicular to $5x - 3y = 9$ and passes through the point $(1, -2)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-7/5', ARRAY['-7/5', '-1.4'], E'First, rewrite $5x - 3y = 9$ in slope-intercept form: $y = \\frac{5}{3}x - 3$, so the slope is $\\frac{5}{3}$. A perpendicular line has slope $-\\frac{3}{5}$. Using point-slope form with $(1, -2)$: $y + 2 = -\\frac{3}{5}(x - 1)$. Expanding gives $y = -\\frac{3}{5}x + \\frac{3}{5} - 2 = -\\frac{3}{5}x - \\frac{7}{5}$. The $y$-intercept is $-\\frac{7}{5}$. A common error is using $\\frac{3}{5}$ (omitting the negative) for the perpendicular slope, which yields a positive $y$-intercept. Another error is using the reciprocal $-\\frac{5}{3}$ instead of the negative reciprocal $-\\frac{3}{5}$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WO4ECS', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'The expression $\\frac{6x^4 - 21x^3 + 9x^2}{3x^2}$ can be written as $2x^2 + bx + c$ for all $x \\neq 0$. What is the value of $b \\cdot c$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-21', ARRAY['-21'], E'Dividing each term of the numerator by $3x^2$: $\\frac{6x^4}{3x^2} = 2x^2$, $\\frac{-21x^3}{3x^2} = -7x$, and $\\frac{9x^2}{3x^2} = 3$. The expression simplifies to $2x^2 - 7x + 3$, so $b = -7$ and $c = 3$. Therefore $b \\cdot c = (-7)(3) = -21$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WTQ7QT', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A chord of a circle is $24$ units long and is $5$ units from the center of the circle. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$144\\pi$"},{"key":"B","text":"$149\\pi$"},{"key":"C","text":"$169\\pi$"},{"key":"D","text":"$288\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'A perpendicular from the center to a chord bisects the chord, creating a right triangle with legs $12$ (half the chord) and $5$ (distance from center). The radius is the hypotenuse: $r = \\sqrt{12^2 + 5^2} = \\sqrt{144 + 25} = \\sqrt{169} = 13$. The area is $\\pi r^2 = 169\\pi$. The value $144\\pi$ comes from using half the chord length ($12$) as the radius. The value $149\\pi$ results from adding $144 + 5$ instead of $144 + 25$. The value $288\\pi$ comes from using the full chord length ($24$) and the distance ($5$) incorrectly as $\\pi(24)(12)$ or a similar dimensional error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XX02GZ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The linear function $g$ satisfies $g(4) = -5$ and $g(-2) = 19$. For what value of $x$ does $g(x) = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11/4', ARRAY['11/4', '2.75'], E'The slope of $g$ is $\\frac{19 - (-5)}{-2 - 4} = \\frac{24}{-6} = -4$. Using the point $(4, -5)$: $g(x) = -4(x - 4) + (-5) = -4x + 16 - 5 = -4x + 11$. Setting $g(x) = 0$ gives $-4x + 11 = 0$, so $x = \\frac{11}{4}$. A common error is computing the slope as $\\frac{24}{6} = 4$ by dropping the negative sign, which leads to the wrong zero. Another error is finding the correct function but solving $g(x) = 0$ incorrectly by dividing $11$ by $4$ with a sign mistake, yielding $-\\frac{11}{4}$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XYLP38', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'What is the value of $x$ that satisfies $\\frac{5x - 2}{3} + \\frac{x + 4}{6} = \\frac{3x + 1}{2}$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3/2', ARRAY['3/2', '1.5'], E'Multiply every term by $6$, the least common denominator, to obtain $2(5x - 2) + (x + 4) = 3(3x + 1)$. Expanding gives $10x - 4 + x + 4 = 9x + 3$, which simplifies to $11x = 9x + 3$. Subtracting $9x$ from both sides yields $2x = 3$, so $x = \\frac{3}{2}$. A common error is choosing an incorrect LCD or distributing the multiplier to only some terms, which leads to an incorrect equation. Another error is dropping the constant terms $-4$ and $+4$ prematurely instead of recognizing that they cancel after distribution.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YD3SHM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'The mean of $9$ test scores is $73$. When a tenth score is added, the mean increases to $76$. What is the tenth score?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '103', ARRAY['103'], E'The sum of the original $9$ scores is $9 \\times 73 = 657$. The sum of all $10$ scores is $10 \\times 76 = 760$. Therefore, the tenth score is $760 - 657 = 103$. A common error is computing $76 - 73 = 3$ and adding that to $76$ to get $79$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YF1H9F', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of length $11$ and $60$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$49$"},{"key":"B","text":"$61$"},{"key":"C","text":"$71$"},{"key":"D","text":"$121$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Pythagorean theorem, $c = \\sqrt{11^2 + 60^2} = \\sqrt{121 + 3600} = \\sqrt{3721} = 61$. The value $49$ comes from subtracting $11$ from $60$ instead of applying the Pythagorean theorem. The value $71$ results from simply adding the two leg lengths. The value $121$ comes from squaring $11$ and treating that intermediate result as the hypotenuse.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YN4FDH', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = 2x^2 - 12x + 23$, and $g$ is defined by $g(x) = f(x - 3)$. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$8$"},{"key":"C","text":"$23$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, rewrite $f(x)$ in vertex form by completing the square: $f(x) = 2(x^2 - 6x) + 23 = 2(x - 3)^2 - 18 + 23 = 2(x - 3)^2 + 5$. The minimum value of $f$ is $5$, occurring at $x = 3$. Since $g(x) = f(x - 3) = 2((x - 3) - 3)^2 + 5 = 2(x - 6)^2 + 5$, the graph of $g$ is a horizontal shift of $f$ to the right by 3 units. A horizontal translation does not change the minimum output value, so the minimum value of $g$ is still $5$ (now occurring at $x = 6$). The distractor $8$ incorrectly adds $3$ to the minimum, confusing horizontal shift with vertical shift. The distractor $23$ uses the constant term of $f$ without completing the square. The distractor $11$ comes from evaluating $f(0) = 23$ and then subtracting $12$, an equation setup error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22TOS71', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Elara Moncrieff has spent fourteen years cataloging bioluminescent organisms in the Celebes Sea. Her team discovered that certain species of comb jellies emit light at wavelengths previously unrecorded in marine fauna. ______ Moncrieff''s findings have prompted three other oceanographic institutes to launch parallel surveys in adjacent waters.', $lyceon_json$[{"key":"A","text":"Regardless,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"On the other hand,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'D', NULL, E'The passage describes a discovery (new wavelengths of bioluminescence) and then states that other institutes launched parallel surveys as a result. The relationship is cause-and-effect, so a causal transition ("Consequently,") is correct. "In contrast," and "On the other hand," both signal opposition, but no contrasting idea is introduced. "Regardless," implies the subsequent action happens despite something, but the surveys are prompted by the findings, not in spite of them.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24GW02A', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Cognitive scientist Dmitri Volkov proposed that bilingual speakers unconsciously activate both language systems even when using only one. His 2019 eye-tracking study showed that Spanish-English bilinguals fixated on Spanish-phonology competitor words while reading English sentences, supporting this co-activation hypothesis. ______ a 2023 replication by Kwon and Haber, which controlled for cognate density more rigorously, found that the competitor-fixation effect disappeared for participants with lower second-language proficiency, suggesting that co-activation may be proficiency-dependent rather than universal.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Moreover,"},{"key":"C","text":"However,"},{"key":"D","text":"Accordingly,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage first presents Volkov''s hypothesis and supporting evidence, then introduces a later study whose findings limit the scope of his claim by showing the effect depends on proficiency level. This is a concessive or contrastive relationship, so "However," is correct. "In other words," signals a restatement, but the 2023 study introduces a qualification, not a paraphrase. "Moreover," signals addition, but the replication partly undermines rather than extends the original finding. "Accordingly," implies the later study follows logically from the first, but it actually introduces a complication that narrows the hypothesis.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW262ZYXH', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a comparative analysis of two textile preservation techniques and wants to highlight a key limitation of freeze-drying compared to vacuum-sealing. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes: (1) Freeze-drying removes moisture from textiles by sublimation, preserving fiber structure without chemical additives. (2) Vacuum-sealing encases textiles in airtight polymer film, preventing oxidation. (3) A 2023 study at the Rijksmuseum conservation lab found that freeze-dried silk samples lost 19% of their tensile strength after seven years, whereas vacuum-sealed silk samples retained 97% of original tensile strength over the same period. (4) Freeze-drying equipment costs approximately 4.5 times more than vacuum-sealing apparatus.', $lyceon_json$[{"key":"A","text":"While freeze-drying preserves fiber structure without chemical additives and vacuum-sealing prevents oxidation through airtight polymer film, both methods aim to protect historical textiles from degradation."},{"key":"B","text":"Freeze-drying, which removes moisture through sublimation, costs approximately 4.5 times more than vacuum-sealing equipment, making it a less accessible option for smaller institutions."},{"key":"C","text":"Although freeze-drying preserves fiber structure through sublimation, a 2023 Rijksmuseum study found that freeze-dried silk lost 19% of its tensile strength over seven years, while vacuum-sealed silk retained 97% of its original strength."},{"key":"D","text":"Vacuum-sealing encases textiles in airtight polymer film to prevent oxidation, and the equipment costs roughly one-fourth as much as freeze-drying apparatus."}]$lyceon_json$::jsonb, 'C', NULL, E'The goal is to highlight a limitation of freeze-drying relative to vacuum-sealing. The option referencing the Rijksmuseum study directly contrasts the two methods on tensile-strength retention, showing that freeze-dried silk deteriorated more, which is a clear performance limitation. The option describing both methods'' general aims presents neutral descriptions without identifying any limitation. The option about equipment cost identifies a drawback of freeze-drying but addresses expense rather than preservation performance, and its inference about smaller institutions is not in the notes. The option focusing on vacuum-sealing''s mechanism and lower cost emphasizes vacuum-sealing''s advantages rather than framing a specific limitation of freeze-drying in comparative terms.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26DSGCX', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes a difference in how the two authors interpret the evidence discussed in both texts?', E'Text 1: Archaeologist Priya Venkatesh interprets the uniform pottery styles found across seventeen Indus Valley sites as evidence of a centralized political authority that imposed standardized production methods. She argues that such consistency is unlikely to emerge without top-down coordination, drawing parallels to the standardized ceramics of the Roman Empire.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW274PSBD', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best describes the main idea of the text?', E'Recent archaeological excavations at a site in northern Peru have uncovered a previously unknown ceremonial platform dating to approximately 1400 BCE. The platform, constructed from sun-dried adobe bricks arranged in a distinctive herringbone pattern, measures roughly 37 meters across and stands 4.5 meters high. Lead archaeologist Mariana Vega noted that the structure''s orientation aligns precisely with the June solstice sunrise, suggesting its builders possessed sophisticated astronomical knowledge. The discovery has prompted researchers to reconsider the timeline of monumental architecture in the region, which was previously believed to have begun several centuries later.', $lyceon_json$[{"key":"A","text":"A newly discovered ceremonial platform in Peru suggests that monumental construction in the region began earlier than scholars had thought."},{"key":"B","text":"Archaeologists have determined that ancient Peruvian builders used adobe bricks exclusively for ceremonial purposes."},{"key":"C","text":"The herringbone brick pattern found at a Peruvian site is unique among all known pre-Columbian structures."},{"key":"D","text":"Mariana Vega's research has overturned the consensus that ancient Peruvian civilizations lacked astronomical expertise."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a ceremonial platform dating to approximately 1400 BCE and states that the discovery has prompted researchers to reconsider the timeline of monumental architecture, which was previously thought to have begun later. The correct answer captures this main idea. The claim that adobe bricks were used exclusively for ceremonial purposes goes beyond what the passage states, which mentions only this particular structure. The assertion that the herringbone pattern is unique among all pre-Columbian structures is not supported; the passage calls it distinctive but does not claim uniqueness across all sites. The suggestion that the consensus held ancient Peruvians lacked astronomical expertise overstates the passage, which says the timeline of monumental architecture is being reconsidered, not that astronomical knowledge was previously denied.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27LNFMB', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Svalbard Global Seed Vault, located on a Norwegian archipelago roughly 800 miles from the North Pole, stores duplicate samples of seeds from gene banks around the world. Designed to withstand both natural and human-caused disasters, the facility is built into the side of a sandstone mountain and cooled to negative eighteen degrees _______ its remote Arctic location provides an additional layer of security against unauthorized access.', $lyceon_json$[{"key":"A","text":"Celsius,"},{"key":"B","text":"Celsius"},{"key":"C","text":"Celsius;"},{"key":"D","text":"Celsius, so"}]$lyceon_json$::jsonb, 'C', NULL, E'The blank sits between two independent clauses: one ending with ''negative eighteen degrees Celsius'' and another beginning with ''its remote Arctic location provides.'' A semicolon correctly joins two independent clauses without a coordinating conjunction. Using only a comma after ''Celsius'' creates a comma splice, which is a sentence boundary error. Omitting punctuation entirely produces a run-on sentence. Using a comma followed by ''so'' implies a cause-and-effect relationship, suggesting that the vault''s cooling system somehow causes the Arctic location to provide security; in fact, the remote location is an independent geographic feature, not a consequence of the temperature, making ''so'' logically inappropriate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2866IYC', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeometallurgist Priya Sengupta analyzed copper ingots recovered from a Bronze Age shipwreck near Sardinia. Isotopic signatures in the ingots matched ore deposits in what is now southeastern Turkey, suggesting long-distance trade networks existed by 1400 BCE. ______ residue analysis of the ship''s hold revealed traces of tin from Cornwall, indicating that the vessel''s trade route spanned an even greater geographic range than the copper evidence alone implied.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"Furthermore,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage first establishes evidence of long-distance trade (copper from Turkey) and then adds a second, reinforcing piece of evidence (tin from Cornwall) that extends the geographic scope even further. The relationship is additive, making "Furthermore," the correct transition. "Similarly," implies a parallel but separate comparison rather than a building-upon of evidence. "Nevertheless," signals concession or contrast, which does not fit because the tin evidence strengthens rather than qualifies the copper finding. "For instance," introduces an example of a prior claim, but the tin evidence is a new finding that expands the conclusion, not an illustration of the same one.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28K18ZD', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the murals painted by the Ancestral Puebloans at Pottery Mound in central New Mexico have suffered significant deterioration since their excavation in the 1950s, conservators at the Maxwell Museum _______ a photographic archive that, combined with infrared reflectography, now enables scholars to reconstruct pigment layers invisible to the unaided eye.', $lyceon_json$[{"key":"A","text":"had been assembling"},{"key":"B","text":"have assembled"},{"key":"C","text":"would assemble"},{"key":"D","text":"assembling"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence contrasts deterioration since the 1950s with the conservators'' response. The present perfect ''have assembled'' correctly indicates an action begun in the past and relevant to the present situation described by ''now enables.'' The past perfect progressive ''had been assembling'' would place the assembly before another past event, but the sentence''s main time frame connects past action to a present result (''now enables''), making past perfect inappropriate. The conditional ''would assemble'' implies a hypothetical or unrealized action, contradicting the factual tone of the passage and the present-tense ''now enables.'' Using ''assembling'' without an auxiliary verb creates a participial phrase that leaves the main clause without a finite verb, producing an incomplete sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW293Z4KN', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Appalachian Trail Conservancy coordinates volunteer crews that maintain the 2,190-mile footpath stretching from Georgia to Maine. Each year, roughly 3,000 _______ clear fallen trees, repair erosion damage, and repaint the white blazes that guide hikers along the route.', $lyceon_json$[{"key":"A","text":"volunteers, who"},{"key":"B","text":"volunteers"},{"key":"C","text":"volunteers, they"},{"key":"D","text":"volunteers that"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence requires a subject for the verbs ''clear,'' ''repair,'' and ''repaint.'' The noun ''volunteers'' alone serves as the subject that directly governs these verbs, completing a grammatically correct sentence. Adding ''who'' after a comma creates a nonrestrictive relative clause, which would make ''clear, repair, and repaint'' part of a subordinate clause rather than the main predicate, leaving the sentence without a main verb. Inserting ''they'' after a comma produces a comma splice by introducing a second independent clause. Adding ''that'' creates a restrictive relative clause modifying ''volunteers,'' which again subordinates the verbs and leaves the main clause incomplete.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29Y2EA3', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice can most reasonably be inferred from the text?', E'Musicologist Renata Sobieski analyzed 243 surviving compositions by the 18th-century Czech composer Jan Dismas Zelenka, comparing their harmonic structures to those of his contemporary Johann Sebastian Bach. While Bach''s fugues typically resolve dissonant passages within 4 to 6 measures, Zelenka''s works frequently sustain unresolved dissonances for 11 to 19 measures, creating what Sobieski terms prolonged harmonic tension. Despite receiving court appointments in Dresden and composing prolifically, Zelenka was rarely performed outside Saxony during his lifetime and remained largely unknown for two centuries after his death. Sobieski posits that Zelenka''s extended dissonances, though structurally innovative, clashed with the prevailing Baroque preference for orderly harmonic resolution, limiting his appeal to contemporary audiences and patrons beyond his immediate court circle.', $lyceon_json$[{"key":"A","text":"Bach's compositions were considered harmonically conservative by most 18th-century music critics."},{"key":"B","text":"Sobieski's analysis demonstrates that Zelenka was a more technically accomplished composer than Bach."},{"key":"C","text":"The Dresden court specifically commissioned Zelenka to compose works featuring extended dissonances as an alternative to Bach's style, with the explicit aim of establishing a distinctive musical identity for the Saxon capital's ceremonial and liturgical occasions."},{"key":"D","text":"Zelenka's relative obscurity during and after his lifetime may have resulted partly from the incompatibility between his compositional style and the harmonic expectations of his era."}]$lyceon_json$::jsonb, 'D', NULL, E'The passage states that Zelenka''s extended dissonances clashed with Baroque preferences for orderly resolution, limiting his appeal beyond his court circle, and that he remained largely unknown for two centuries. From this, one can reasonably infer that the mismatch between his style and contemporary harmonic expectations contributed to his obscurity. The claim that Bach was considered harmonically conservative is not supported; the passage uses Bach as a reference point for typical Baroque practice but does not characterize critics'' views of him. The assertion that the Dresden court specifically commissioned extended dissonances, with an aim of establishing a distinctive musical identity, is fabricated; the passage says only that Zelenka received court appointments. The conclusion that Zelenka was more technically accomplished than Bach is not supported; Sobieski''s analysis compares harmonic structures but does not rank the composers'' technical skill.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 95, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29YYNJ7', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'In a study of urban noise pollution, acoustics researcher David Yeung measured ambient sound levels at 139 intersections across Seoul between 6 a.m. and 10 p.m. He found that intersections bordered by buildings taller than 40 meters had average noise levels 8.3 decibels higher than intersections in low-rise neighborhoods, even when traffic volume was comparable. Yeung attributed this difference to the acoustic phenomenon known as the canyon effect, in which sound waves bounce repeatedly between tall parallel surfaces rather than dissipating upward. This finding suggests that urban planners seeking to reduce street-level noise exposure should consider ________', $lyceon_json$[{"key":"A","text":"increasing speed limits at intersections surrounded by tall buildings to reduce the duration of vehicle noise at any single point."},{"key":"B","text":"incorporating design features that interrupt the parallel alignment of tall building facades along major roadways."},{"key":"C","text":"mandating that all new residential construction exceed 40 meters in height to ensure uniform sound distribution."},{"key":"D","text":"relocating commercial traffic routes away from low-rise neighborhoods where noise complaints are most frequent."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage establishes that the canyon effect — sound bouncing between tall parallel surfaces — causes elevated noise levels. A logical intervention would address the mechanism by disrupting the parallel alignment of building facades, which is what the correct answer proposes. Increasing speed limits would not address the reflective amplification and could increase noise generation. Mandating buildings over 40 meters would worsen the canyon effect, not reduce noise. Relocating traffic from low-rise neighborhoods misidentifies where the problem is most severe; the passage shows noise is worse in high-rise areas, not low-rise ones.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ARSW3O', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Paleontologist Darla Zelenitsky argues that the gigantic body size of sauropod dinosaurs was primarily an adaptation for thermoregulation. Larger bodies retain heat more efficiently, which would have allowed sauropods to maintain stable internal temperatures in fluctuating climates.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B4QDLD', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Although the Renaissance composer Josquin des Prez was celebrated during his lifetime, the attribution of many works to him remained __________ for centuries. Musicologist Jesse Rodin has demonstrated that publishers eager to capitalize on Josquin''s fame routinely attached his name to pieces by lesser-known contemporaries, inflating his catalogue well beyond its authentic boundaries.', $lyceon_json$[{"key":"A","text":"obsolete"},{"key":"B","text":"lucrative"},{"key":"C","text":"notorious"},{"key":"D","text":"spurious"}]$lyceon_json$::jsonb, 'D', NULL, E'The passage describes how publishers falsely credited works to Josquin that were actually composed by others, making those attributions inauthentic. "Spurious" means not genuine or based on false reasoning, which precisely captures attributions that were fabricated by publishers seeking profit. "Lucrative" means financially profitable, which describes the publishers'' motive but not the nature of the attributions themselves, producing an incoherent description of how works were credited. "Notorious" means famous for something bad, which does not describe the quality of being falsely assigned and creates a semantically mismatched sentence. "Obsolete" means no longer in use or outdated, which implies the attributions became irrelevant over time rather than being fraudulent from the start, contradicting the passage''s central point about deliberate misattribution.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DN5DMN', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2023 study published in the journal Ecology Letters, researcher Priya Deshmukh demonstrated that the root systems of balsam fir trees in Quebec''s boreal forests _______ chemical signals to neighboring saplings when bark beetle larvae begin boring into the parent tree''s cambium layer. This underground communication network enables younger trees to preemptively produce defensive resins.', $lyceon_json$[{"key":"A","text":"transmits"},{"key":"B","text":"transmit"},{"key":"C","text":"has transmitted"},{"key":"D","text":"is transmitting"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the verb is ''root systems,'' which is plural. The passage describes a general biological behavior demonstrated by a study, requiring a present-tense plural verb. The plural form ''transmit'' agrees with ''systems.'' The singular ''transmits'' fails to agree with the plural subject ''root systems.'' The singular ''has transmitted'' also fails in number agreement and shifts the tense to present perfect, implying a completed action rather than an ongoing biological process. The singular progressive ''is transmitting'' likewise fails in number agreement and inappropriately suggests the action is occurring at one specific moment rather than describing a general behavior.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FCWLZQ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice most accurately describes the central claim the author develops in the text?', E'Historians have long attributed the decline of the medieval Hanseatic League primarily to the rise of nation-states that imposed tariffs on cross-border trade. However, recent analyses of merchant correspondence from the 1470s reveal a subtler dynamic. Internal disputes over standardized weights and measures — particularly between Lubeck''s silver-mark system and Danzig''s grain-based reckoning — eroded trust among member cities well before external political pressures intensified. When Hamburg unilaterally adopted a third measurement protocol in 1478, several smaller ports severed their trade agreements entirely, fragmenting the network from within. External tariffs merely accelerated a dissolution that internal disunity had already set in motion.', $lyceon_json$[{"key":"A","text":"The Hanseatic League collapsed because Hamburg's measurement protocol was economically inferior to those of Lubeck and Danzig."},{"key":"B","text":"Nation-states played a negligible role in the decline of the Hanseatic League, which was driven entirely by internal disputes over weights and measures among member cities that were unwilling to harmonize their established local trading conventions."},{"key":"C","text":"The decline of the Hanseatic League was initiated by internal disagreements over measurement standards, with external political pressures serving as an accelerating factor rather than the primary cause."},{"key":"D","text":"The Hanseatic League might have survived if its member cities had adopted Lubeck's silver-mark system as a universal standard."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage argues that internal disputes over measurement standards — not external tariffs — initiated the League''s decline, and that external pressures merely accelerated a dissolution already underway. The correct answer captures this nuanced central claim. The assertion that Hamburg''s protocol was economically inferior misreads the passage, which says Hamburg''s unilateral adoption of a different protocol caused fragmentation, not that the protocol itself was inferior. The claim that nation-states played a negligible role overstates the passage''s argument; the text says external tariffs accelerated the decline, acknowledging their contributory role. The suggestion that the League might have survived under Lubeck''s system is speculative and not a claim the author makes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HICNOE', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1847, physician Ignaz Semmelweis observed that the maternity ward staffed by medical students had a mortality rate nearly five times higher than the ward staffed by midwives. He hypothesized that students were transferring harmful material from cadaver dissections to laboring patients. After Semmelweis instituted mandatory handwashing with a chlorinated solution, the mortality rate in the students'' ward plummeted to levels comparable to the midwives'' ward. Yet the medical establishment largely rejected his findings, partly because germ theory had not yet been articulated.', $lyceon_json$[{"key":"A","text":"It presents an observation, describes the intervention it prompted, and notes a paradoxical response to the results."},{"key":"B","text":"It compares two competing medical theories and evaluates the experimental evidence supporting each one."},{"key":"C","text":"It chronicles the career of a physician in strict chronological order without commenting on the significance of his work."},{"key":"D","text":"It argues that modern hygiene practices are inadequate and proposes a return to nineteenth-century protocols."}]$lyceon_json$::jsonb, 'A', NULL, E'The text follows a clear three-part arc: Semmelweis notices a mortality disparity (observation), he introduces handwashing which drastically reduces deaths (intervention), and the medical community nevertheless dismisses his findings (paradoxical response). The option describing an observation, an intervention, and a paradoxical response captures this structure accurately. The option about two competing theories is wrong because the passage presents only Semmelweis''s hypothesis, not a rival theory. The option about strict chronological career chronicle omits the text''s evaluative final sentence about rejection and reduces the passage to mere timeline. The option about arguing modern hygiene is inadequate introduces a claim the passage never makes; it discusses nineteenth-century events without advocating any policy.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K02RMB', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The memoir''s final chapter—in which the author recounts her expedition to map a chain of underwater caves beneath the Yucatán Peninsula_______ takes an unexpectedly philosophical turn, questioning whether the impulse to explore unmapped terrain reflects genuine scientific curiosity or a compulsion to court danger.', $lyceon_json$[{"key":"A","text":"Peninsula, takes"},{"key":"B","text":"Peninsula; takes"},{"key":"C","text":"Peninsula. Takes"},{"key":"D","text":"Peninsula—takes"}]$lyceon_json$::jsonb, 'D', NULL, E'An em dash before "in which" opens a parenthetical aside that interrupts the main clause. Paired parenthetical dashes must be closed with a matching em dash, so the closing mark after "Peninsula" must also be an em dash. This correctly reconnects the subject "The memoir''s final chapter" with its predicate "takes an unexpectedly philosophical turn." A comma cannot close a dash-opened parenthetical; mixing punctuation types in a paired construction violates standard conventions for setting off interruptive elements. A semicolon is incorrect because no independent-clause boundary exists between the subject and its verb; inserting a semicolon would sever the subject from its predicate. A period would leave the subject and its parenthetical aside as a sentence fragment without a main verb and would also orphan "Takes" from its subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KNFL5L', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which choice most effectively uses data from the text to support the argument that lunar regolith composition varies significantly by location?', E'Spectroscopic analyses conducted by the Chandrayaan-3 lander in August 2023 detected sulfur concentrations of approximately 2.9 percent in regolith samples near the lunar south pole — a figure roughly three times higher than the 0.9 percent measured by Apollo 17 at the Taurus-Littrow valley, which sits at 20 degrees north latitude. Additionally, Chandrayaan-3 recorded iron oxide levels of 14.7 percent, compared to Apollo 17''s 22.3 percent. These compositional divergences align with models predicting that volcanic resurfacing events, which were more prevalent in equatorial and mid-latitude mare basins, would produce mineralogically distinct regolith profiles at different latitudes.', $lyceon_json$[{"key":"A","text":"The Chandrayaan-3 lander used spectroscopic methods comparable to those employed during the Apollo 17 mission, ensuring that measurements from both sites could be meaningfully compared, which is an important methodological prerequisite for any rigorous cross-site analysis of lunar surface geochemistry."},{"key":"B","text":"Sulfur concentrations at the south pole were approximately three times higher than those at the Taurus-Littrow valley, while iron oxide levels showed the inverse pattern, with south-pole samples containing roughly 34 percent less iron oxide."},{"key":"C","text":"Volcanic resurfacing events occurred more frequently near the equator than at the poles, explaining why all lunar regolith eventually becomes chemically homogeneous over geological timescales."},{"key":"D","text":"The Chandrayaan-3 mission was the first to successfully land near the lunar south pole, providing data from a region previously inaccessible to direct sampling."}]$lyceon_json$::jsonb, 'B', NULL, E'The argument concerns compositional variation by location. The correct answer cites specific data from both sites — sulfur approximately three times higher at the south pole and iron oxide roughly 34 percent lower — directly demonstrating that regolith composition differs significantly between the two locations. The point about comparable spectroscopic methods and their importance as a methodological prerequisite addresses methodological validity, not compositional variation itself, so it does not support the argument about varying composition. The claim that volcanic resurfacing explains chemical homogeneity directly contradicts both the passage and the argument; the passage states these events produced mineralogically distinct profiles, not homogeneous ones. The observation that Chandrayaan-3 was the first south-pole landing addresses mission history, not the compositional data needed to support the argument.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 95, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KO98MG', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists at the University of Bergen have hypothesized that the sharp decline in Atlantic puffin populations along Norway''s western coast since 2011 is linked to rising sea-surface temperatures, which have pushed sand eel schools — puffins'' primary prey — into deeper, colder waters beyond the birds'' typical diving range. The researchers predict that puffin colonies at higher latitudes, where sea-surface warming has been less pronounced, should be experiencing comparatively stable population numbers.', $lyceon_json$[{"key":"A","text":"Puffin colonies on the Svalbard archipelago, located at 78 degrees north, have maintained population levels consistent with their 2005 baseline counts."},{"key":"B","text":"Sand eel populations throughout the North Atlantic have declined by 60 percent since 2003 due to commercial overfishing."},{"key":"C","text":"Atlantic puffins have been observed switching to a diet of juvenile herring in regions where sand eels are scarce."},{"key":"D","text":"Sea-surface temperatures along Norway's western coast have risen by an average of 1.7 degrees Celsius since 2000."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers'' hypothesis predicts that puffin colonies at higher latitudes, where warming is less pronounced, should have stable populations. The finding that colonies on Svalbard (78 degrees north) have maintained their baseline population counts directly confirms this prediction. The finding about sand eel decline from overfishing would suggest an alternative cause unrelated to temperature, undermining rather than supporting the hypothesis. The observation about puffins switching diets addresses behavioral adaptation but does not confirm the temperature-driven mechanism. The finding about rising sea-surface temperatures along the western coast describes a background condition already assumed by the hypothesis, not evidence that the mechanism (temperature driving prey deeper) is actually causing puffin decline.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NA84ZH', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The volcanic island of Surtsey, which emerged from the North Atlantic in 1963, has served as a uniquely controlled natural laboratory. Because scientists restricted human access from the outset, ecological succession on Surtsey has proceeded without the __________ that typically complicates studies of newly formed landmasses, such as the introduction of non-native species by visitors.', $lyceon_json$[{"key":"A","text":"interference"},{"key":"B","text":"demolition"},{"key":"C","text":"encryption"},{"key":"D","text":"allegiance"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage explains that restricting human access allowed ecological processes to proceed undisturbed, and the blank requires a word describing unwanted human disruption. "Interference" means unwanted involvement that hinders a process, which precisely captures how human visits introducing non-native species would complicate ecological studies. "Demolition" refers to the deliberate destruction of structures, which is incoherent in the context of ecological succession. "Encryption" refers to encoding information for security, a concept entirely unrelated to ecological fieldwork. "Allegiance" means loyalty or devotion, which produces a nonsensical reading when describing what complicates scientific studies of new landmasses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PTD4M1', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, which choice best describes the relationship between mycorrhizal networks and the trees they connect?', E'Ecologist Suzanne Simard''s research in British Columbia''s old-growth forests has revealed that Douglas fir trees transfer carbon to neighboring western red cedars through underground mycorrhizal networks — threadlike fungal structures that link the root systems of different trees. Simard found that the transfer intensified when recipient cedars were shaded, receiving up to 43 percent more carbon than their sunlit counterparts. Critically, the exchange is not unidirectional: cedars reciprocate by sending phosphorus-rich compounds back to the firs during autumn, when the deciduous understory drops its leaves. This bidirectional nutrient exchange suggests the network functions less as a passive conduit and more as an active system modulated by each partner''s seasonal requirements.', $lyceon_json$[{"key":"A","text":"The trees use the networks primarily to compete for limited underground resources."},{"key":"B","text":"The networks are maintained exclusively by the fungal organisms, with no metabolic cost to the trees involved."},{"key":"C","text":"The networks allow fir trees to dominate cedars by absorbing a disproportionate share of available phosphorus, thereby gaining a sustained competitive advantage in nutrient-limited forest soils."},{"key":"D","text":"The trees exchange nutrients through the networks in a reciprocal manner influenced by seasonal and environmental conditions."}]$lyceon_json$::jsonb, 'D', NULL, E'The passage describes a bidirectional exchange: Douglas firs send carbon to cedars (especially shaded ones), and cedars return phosphorus-rich compounds to firs in autumn. This reciprocal transfer is modulated by seasonal requirements and light conditions. The correct answer captures this mutual, condition-dependent exchange. The claim that trees use the networks primarily to compete contradicts the passage''s emphasis on cooperation and reciprocity. The assertion that firs dominate cedars by absorbing phosphorus reverses the described direction — cedars send phosphorus to firs, not the other way around. The suggestion that networks are maintained exclusively by fungi with no cost to trees is not addressed in the passage, which focuses on nutrient exchange rather than network maintenance costs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QHQSKS', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which choice best describes data that would weaken the claim presented in the text?', E'A 2024 study by agricultural economists at Wageningen University concluded that vertical farming operations in the Netherlands consume, on average, 71 percent less water per kilogram of leafy greens produced than conventional field agriculture in the same region. The researchers attributed this efficiency primarily to closed-loop hydroponic recirculation systems that capture and reuse transpired moisture. Based on these findings, the study''s authors argued that scaling vertical farming could substantially reduce freshwater withdrawals in water-stressed agricultural regions globally.', $lyceon_json$[{"key":"A","text":"Findings that hydroponic nutrient solutions must be replaced every 14 days to prevent bacterial contamination."},{"key":"B","text":"Evidence that Dutch conventional farms already use more advanced irrigation technology, including precision drip-feed and subsurface delivery networks, than farms in most other countries, potentially making the Netherlands an unrepresentative baseline for global comparison."},{"key":"C","text":"A report indicating that consumer demand for vertically farmed produce has increased by 38 percent since 2021."},{"key":"D","text":"Data showing that vertical farms in arid regions require extensive supplemental cooling systems that consume large volumes of water, offsetting the savings from hydroponic recirculation."}]$lyceon_json$::jsonb, 'D', NULL, E'The authors'' claim is that scaling vertical farming could substantially reduce freshwater withdrawals in water-stressed regions globally. Data showing that vertical farms in arid regions require water-intensive cooling that offsets hydroponic savings would directly challenge the claim''s applicability to water-stressed areas. Evidence that Dutch conventional farms use advanced irrigation, including precision drip-feed and subsurface delivery, would suggest the 71 percent savings might not generalize, but it does not directly show that vertical farming fails to save water in other regions — it merely questions the comparison baseline. Increased consumer demand for vertical produce addresses market viability, not water efficiency, and is irrelevant to the claim. The finding about nutrient solution replacement addresses operational maintenance but does not quantify water consumption impacts or challenge the overall water-savings claim.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 85, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QPFZGE', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Researchers studying monarch butterfly migration have long been impressed by the insects'' ability to navigate thousands of miles with remarkable accuracy. Even when displaced to unfamiliar locations, monarchs can rapidly __________ their course and resume traveling toward their overwintering sites in central Mexico.', $lyceon_json$[{"key":"A","text":"rectify"},{"key":"B","text":"fabricate"},{"key":"C","text":"abandon"},{"key":"D","text":"obscure"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes monarchs that, after being displaced, adjust their navigation to head toward the correct destination. "Rectify" means to correct or put right, which precisely matches the idea of fixing a course after displacement. "Fabricate" means to invent or manufacture something, which is incoherent when applied to correcting a travel route. "Abandon" means to give up entirely, which contradicts the passage''s statement that the butterflies resume traveling. "Obscure" means to conceal or make unclear, which is nonsensical in the context of correcting a navigational path.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QRFIND', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second sentence in the text?', E'Linguist Shana Poplack''s research on code-switching among bilingual speakers in Ottawa challenged the prevailing view that mixing languages within a single conversation signals linguistic deficiency. Her large-scale corpus analysis revealed that switches between French and English follow highly systematic grammatical constraints, occurring at specific syntactic boundaries rather than at random points. Subsequent studies in communities spanning Welsh-English, Spanish-English, and Swahili-English bilingualism have corroborated these findings, suggesting that the structural regularities Poplack identified are not artifacts of a single language pair.', $lyceon_json$[{"key":"A","text":"It summarizes the conclusions of the subsequent studies mentioned later in the passage."},{"key":"B","text":"It qualifies Poplack's findings by identifying a methodological limitation in her corpus analysis."},{"key":"C","text":"It contrasts Poplack's approach with the methods used by researchers discussed in the third sentence."},{"key":"D","text":"It presents the specific evidence that undermined the assumption introduced in the first sentence."}]$lyceon_json$::jsonb, 'D', NULL, E'The first sentence states that Poplack challenged the view that code-switching indicates deficiency. The second sentence then provides the empirical basis for that challenge: her corpus analysis showed switches follow systematic grammatical rules, not random patterns. The option stating it presents specific evidence that undermined the assumption in the first sentence accurately describes this function. The option about methodological limitations is incorrect because the second sentence describes findings, not flaws. The option about contrasting methods misidentifies the relationship; the second sentence describes Poplack''s own results, not a comparison with later researchers. The option about summarizing subsequent studies confuses the second sentence''s content with the third sentence, which is the one that discusses corroborating research.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SGYNCK', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a report about urban beekeeping and wants to emphasize the economic benefit that rooftop hives provide to local businesses. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes: (1) Since 2018, rooftop apiaries in Portland, Oregon, have increased from 37 to 214. (2) A 2024 Portland State University study found that restaurants sourcing honey from rooftop hives within two miles saved an average of \\$1,740 annually on honey procurement costs. (3) Rooftop hives also support pollination of nearby community gardens. (4) Portland''s municipal code permits up to four hives per residential rooftop.', $lyceon_json$[{"key":"A","text":"Portland's municipal code allows up to four beehives on any residential rooftop, and the number of rooftop apiaries in the city has grown from 37 to 214 since 2018."},{"key":"B","text":"According to a 2024 Portland State University study, restaurants that source honey from nearby rooftop hives save an average of \\$1,740 per year on procurement costs."},{"key":"C","text":"Rooftop apiaries in Portland have grown rapidly since 2018, and the hives also help pollinate community gardens in surrounding neighborhoods."},{"key":"D","text":"Since 2018, rooftop beekeeping in Portland has expanded significantly, with the number of apiaries increasing from 37 to 214 across the city."}]$lyceon_json$::jsonb, 'B', NULL, E'The goal is to emphasize the economic benefit to local businesses. The option citing the Portland State University finding about restaurants saving \\$1,740 annually directly addresses cost savings for businesses. The option combining municipal code details with growth statistics describes regulatory and expansion facts but says nothing about economic impact. The option about growth and community-garden pollination highlights ecological benefits rather than financial ones. The option describing the increase from 37 to 214 apiaries focuses on growth statistics without connecting them to any business advantage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TYPWAT', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a research summary and wants to present the findings of Okoro''s study in a way that acknowledges the prior consensus while showing how Okoro''s results complicate it. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes: (1) Since the 1990s, ornithologists have held that migratory songbirds select stopover sites primarily based on food abundance. (2) Ekemini Okoro''s 2024 radio-telemetry study tracked 438 Swainson''s thrushes across 11 stopover sites in the central flyway. (3) Okoro found that thrushes preferentially selected stopover sites with dense understory canopy, even when nearby open-canopy sites offered 34% greater arthropod biomass. (4) Okoro hypothesized that predation-avoidance cues may override foraging optimization in stopover selection.', $lyceon_json$[{"key":"A","text":"Ekemini Okoro tracked 438 Swainson's thrushes using radio telemetry across 11 stopover sites and discovered that the birds preferred dense understory canopy, leading Okoro to hypothesize that predation-avoidance cues play a role in stopover selection."},{"key":"B","text":"Okoro's radio-telemetry study of 438 Swainson's thrushes found that the birds selected stopover sites with dense understory canopy, and Okoro suggested that predation-avoidance cues are important factors in migratory behavior."},{"key":"C","text":"Since the 1990s, the prevailing view among ornithologists has been that migratory songbirds choose stopover sites primarily based on food availability, and Okoro's comprehensive radio-telemetry study of Swainson's thrushes examined this established question by tracking 438 individual birds across 11 distinct central-flyway stopover locations during autumn migration."},{"key":"D","text":"Although ornithologists have long attributed migratory stopover selection to food abundance, Okoro's 2024 study found that Swainson's thrushes chose sites with dense understory canopy over sites offering 34% more arthropod prey, suggesting that predation-avoidance cues may outweigh foraging considerations."}]$lyceon_json$::jsonb, 'D', NULL, E'The goal requires two rhetorical moves: acknowledging the prior consensus (food abundance drives stopover selection) and showing how Okoro''s results complicate that consensus. The option beginning with "Although ornithologists have long attributed" explicitly sets up the prior view and then contrasts it with Okoro''s finding that thrushes chose dense-canopy sites despite lower food availability, fulfilling both requirements. The option describing Okoro''s tracking methods and canopy preference presents the new findings but never mentions the prior consensus it complicates. The option outlining the prevailing view and Okoro''s methodology acknowledges the consensus but only describes the study''s design without presenting the complicating results. The option summarizing Okoro''s findings and hypothesis reports results without framing them against the established view, so the reader cannot see how the findings challenge prior understanding.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TZF2H0', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Based on the texts, how would the author of Text 2 most likely characterize the approach described in Text 1?', E'Text 1: Urban planner Reina Matsuda advocates for bioswale corridors along major roadways as the most effective solution to stormwater runoff in dense cities. She cites pilot projects in Portland showing that vegetated bioswales reduced peak runoff volume by 43 percent over a three-year period.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y23Z4G', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the last sentence in the text?', E'The platypus is one of only five surviving species of monotremes, mammals that lay eggs rather than giving birth to live young. Found exclusively in eastern Australia, the platypus inhabits freshwater rivers and streams. It hunts aquatic invertebrates by detecting the faint electrical impulses generated by its prey''s muscle contractions. This electroreception ability, housed in specialized receptors in its bill, makes the platypus one of the few mammals capable of sensing electrical fields.', $lyceon_json$[{"key":"A","text":"It introduces a specific capability that distinguishes the platypus from most other mammals."},{"key":"B","text":"It challenges a widely held assumption about the limitations of mammalian sensory systems."},{"key":"C","text":"It provides evidence that the platypus is more closely related to reptiles than to other mammals."},{"key":"D","text":"It explains why the platypus population has declined in recent decades."}]$lyceon_json$::jsonb, 'A', NULL, E'The final sentence states that electroreception makes the platypus one of the few mammals that can sense electrical fields, thereby identifying a specific sensory ability that sets it apart. The option stating it introduces a specific capability that distinguishes the platypus from most other mammals accurately captures this function. The option about challenging assumptions about mammalian sensory systems goes beyond the text, which presents the fact without framing it as overturning any prior belief. The option about reptile relationships is unsupported; the passage never discusses evolutionary kinship to reptiles. The option about population decline introduces a topic entirely absent from the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZIYJNF', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Entomologist Clara Dietrich studied the foraging behavior of black garden ants (Lasius niger) across 27 colonies in Brandenburg, Germany. She observed that when a scout ant discovered a sucrose solution at a feeder 11 meters from the nest, the number of nestmates arriving at the feeder within 30 minutes averaged 74. However, when the same concentration of sucrose was placed at a feeder just 3 meters away, the average number of recruits in the same period was only 51. Dietrich hypothesized that scouts returning from more distant sources deposit pheromone trails over a longer path, which ________', $lyceon_json$[{"key":"A","text":"degrade more rapidly, causing recruited ants to abandon the trail before reaching the food source."},{"key":"B","text":"create a stronger cumulative chemical signal that recruits more nestmates to follow the trail."},{"key":"C","text":"confuse nestmates because the pheromone concentration per unit distance is lower on longer trails."},{"key":"D","text":"attract predatory species that intercept recruited ants, reducing the colony's overall foraging efficiency."}]$lyceon_json$::jsonb, 'B', NULL, E'The data shows that more ants arrived at the distant feeder (74) than at the nearby one (51). Dietrich''s hypothesis must explain why greater distance led to greater recruitment. A longer path means more total pheromone deposited, creating a stronger cumulative signal that recruits more nestmates — this is the only explanation consistent with the observed data. The suggestion that longer trails degrade faster would predict fewer recruits at greater distances, contradicting the observations. The claim about lower concentration per unit distance causing confusion would also predict fewer recruits, not more. Predatory interception is unrelated to the recruitment data and is not supported by anything in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 85, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZPVY02', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Bayeux Tapestry, which is actually an embroidered cloth rather than a woven tapestry_______ depicts the events leading to the Norman conquest of England in 1066 across a narrative strip that stretches nearly seventy meters in length.', $lyceon_json$[{"key":"A","text":"tapestry, depicts"},{"key":"B","text":"tapestry depicts"},{"key":"C","text":"tapestry; depicts"},{"key":"D","text":"tapestry. Depicts"}]$lyceon_json$::jsonb, 'A', NULL, E'The phrase "which is actually an embroidered cloth rather than a woven tapestry" is a nonrestrictive relative clause set off by commas. Because a comma opens the clause after "Tapestry," a matching comma must close it after "tapestry" to complete the pair before the main verb "depicts." Omitting the closing comma leaves the nonrestrictive clause unpaired, creating a grammatical error in which the boundary between the modifying clause and the main predicate is lost. A semicolon incorrectly separates the subject from its predicate, since no independent clause boundary exists at the blank; the subject "The Bayeux Tapestry" and its verb "depicts" belong to the same clause. A period would leave the preceding material without a complete main clause and orphan "Depicts" from its subject, producing a fragment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
